-- Rollback: put back the stances in docs/seed-snapshots/2026-11-07-debate-topics.json.
-- debate_topics, stances only, one row per statement. Each UPDATE takes ROW EXCLUSIVE on
-- the table and a row lock on its one row, held for milliseconds; it can wait only on a
-- concurrent par_elo update to the same row by /api/judge.
begin;
update public.debate_topics set stances = $stances${"stoicism":"Deploy it if the people responsible judged the evidence well; the mechanism is an external, and a sound judgement does not become unsound because the reasons cannot be passed on.","virtue-ethics":"Do not deploy it, because justice to the person a decision lands on includes owing them an answer, and a practice of withholding one forms the wrong character.","utilitarianism":"Deploy it, because the suffering it prevents is real and an explanation was only ever a means to that end."}$stances$::jsonb where slug = 'opaque-benefit';
update public.debate_topics set stances = $stances${"stoicism":"Whatever the rule is, it must be one a rational passenger could assent to before getting in, so the wrong lies in concealing the rule, not in the count.","virtue-ethics":"No rule written in advance can stand in for the judgement a wise person would exercise in the moment, so the real question is whether the engineers deliberated justly, not whether their arithmetic balances.","utilitarianism":"Two deaths are worse than one whoever the one is, and a rule that counts the passenger as exactly one person is the only impartial rule on offer."}$stances$::jsonb where slug = 'crash-arithmetic';
update public.debate_topics set stances = $stances${"stoicism":"A decision is assent to an impression by a ruling faculty, and a model has neither, so the word is misapplied however determined the output.","virtue-ethics":"Choice is deliberate desire formed by character, and a system with no character cannot choose, which is why calling its output a decision quietly moves responsibility off the people who trained it.","utilitarianism":"Whether there is a decision inside the box changes nothing about what the output does to people, so the mistake, if it is one, does not matter."}$stances$::jsonb where slug = 'no-decision';
update public.debate_topics set stances = $stances${"stoicism":"Goodness is correct assent, and a model has no impressions to assent to, so training makes it a well-made tool, which is neither good nor bad.","virtue-ethics":"Habit makes a person good only once they choose the act for its own sake from a settled character, and reward shaping produces the acts without the state.","utilitarianism":"If the trained behaviour reliably produces good outcomes then it is good in the only sense that counts, and how it got there is a detail."}$stances$::jsonb where slug = 'moral-training';
update public.debate_topics set stances = $stances${"stoicism":"Blame attaches to judgement, not to fortune, so a builder who judged well and was unlucky is blameless whatever the damage.","virtue-ethics":"A good person carries the weight of harm they caused even when blameless, so proportional blame is mistaken while a builder who shrugs reveals a defect of character.","utilitarianism":"Blame is a tool for changing future behaviour, so it should track what would have prevented the harm, and punishing care that failed by chance prevents nothing."}$stances$::jsonb where slug = 'careful-builder';
update public.debate_topics set stances = $stances${"stoicism":"The only thing that is truly yours is the faculty that judges impressions, and handing that over is the one loss no better outcome can repay.","virtue-ethics":"Practical wisdom exists only in the person who exercises it, so a life of delegated choices is one in which you never become anyone in particular.","utilitarianism":"Nothing that matters is lost unless your life goes worse, and if the choices are better and you are happier then the worry about whose judgement it was is sentiment."}$stances$::jsonb where slug = 'borrowed-judgement';
commit;
